<?phpnamespace app\store\controller\plat\weixin\wechat;use app\store\controller\Controller;use app\store\model\WechatBatchSend as WechatBatchSendModel;use think\facade\View;/** * 微信群发消息控制器 */class Send extends Controller{	/**     * 首页     */    public function index()    {        $model = new WechatBatchSendModel;        $list = $model->getList();        return View::fetch('index', compact('list'));    }    /**     * 添加     */    public function add()    {        if ($this->request->isPost()) {            $model = new WechatBatchSendModel;            // 新增记录            if ($model->add($this->postData('data'))) {                return $this->renderSuccess('添加成功，预览消息已发送到管理员微信', url('plat.weixin.wechat.send/index'));            }            $error = $model->getError() ?: '添加失败';            return $this->renderError($error);        }        return redirect(url('plat.weixin.wechat.send/index'));       }        /**     * 编辑     */    public function edit(int $id)    {        $model = WechatBatchSendModel::get($id);        if ($this->request->isGet()) {            if($model){               return $this->renderSuccess('', '', compact('model'));             }            return $this->renderError('获取失败');        }        // 更新记录        if ($model->edit($this->postData('data'))) {            return $this->renderSuccess('更新成功', url('plat.weixin.wechat.send/index'));        }        $error = $model->getError() ?: '更新失败';        return $this->renderError($error);    }         /**     * 删除     */    public function delete()    {        $data = $this->postData();        $model = WechatBatchSendModel::get($data['id']);        if ($model->remove()) {            return $this->renderSuccess('删除成功');        }        $error = $model->getError() ?: '删除失败';        return $this->renderError($error);    }	/**     * 群发     */    public function status()    {        $data = $this->postData();        $model = WechatBatchSendModel::get($data['id']);        if ($model->send()){            return $this->renderSuccess('群发成功');        }        $error = $model->getError() ?: '群发失败';        return $this->renderError($error);    }}